fun scheduleReminder(context: Context, at: Long) {
    val am = context.getSystemService(AlarmManager::class.java)
    if (!am.canScheduleExactAlarms()) {
        showSettingsPrompt()          // ACTION_REQUEST_SCHEDULE_EXACT_ALARM
        return
    }
    val pi = PendingIntent.getBroadcast(
        context, 0,
        Intent(context, ReminderReceiver::class.java),
        PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
    )
    am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP, at, pi)
}

fun ensureChannel(context: Context) {
    val channel = NotificationChannel(
        "messages", "Messages",
        NotificationManager.IMPORTANCE_HIGH      // heads-up capable
    ).apply {
        description = "Chat messages"
        enableVibration(true)
    }
    context.getSystemService(NotificationManager::class.java)
        .createNotificationChannel(channel)
}

val requestNotifPermission = registerForActivityResult(
    ActivityResultContracts.RequestPermission()
) { granted -> if (granted) postMessageNotification() }

fun onFirstMessage() {
    val granted = ContextCompat.checkSelfPermission(
        this, Manifest.permission.POST_NOTIFICATIONS
    ) == PackageManager.PERMISSION_GRANTED
    if (granted) postMessageNotification() else requestNotifPermission.launch(
        Manifest.permission.POST_NOTIFICATIONS
    )
}

