ViewCompat.setOnApplyWindowInsetsListener(root) { view, insets ->
    val bars = insets.getInsets(WindowInsetsCompat.Type.systemBars())
    val cutout = insets.getInsets(WindowInsetsCompat.Type.displayCutout())
    val top = maxOf(bars.top, cutout.top)
    val bottom = maxOf(bars.bottom, cutout.bottom)

    // top bar pads down from the status bar
    topBar.updatePadding(top = top)
    // bottom sheet clears the gesture pill
    bottomSheet.updatePadding(bottom = bottom)
    // the list scrolls under the bars but clears them at the end
    list.updatePadding(bottom = bottom)

    insets   // returning it keeps it unconsumed for descendants
}

